{
  "name": "pairwise_preference_signal_loss",
  "intuition": "This loss promotes preferred pairwise comparisons by emphasizing the difference in log probabilities weighted by the difference in quality signals like advantage or cost gap. By using logsigmoid on the difference of log probabilities scaled by advantage differences, it encourages the model to assign higher probabilities to better-ranked options, aligning with the preference structure in RL4CO.",
  "pseudocode": "loss = mean( logsigmoid( (log_prob_w - log_prob_l) * (advantage_w - advantage_l) ) )",
  "hyperparams": {
    "paradigm_family": "preference",
    "signal_family": "advantage",
    "link_family": "logarithmic",
