{
  "name": "pairwise_preference_loss",
  "intuition": "This loss computes a pairwise preference score based on the difference in log probabilities weighted by the cost gap, emphasizing the preference for lower-cost options. Using logsigmoid on the cost gap scaled by the advantage signals encourages the model to assign higher probabilities to better options, aligning with the goal of preference ranking in RL4CO.",
  "pseudocode": "preference_score = logsigmoid((log_prob_w - log_prob_l) * (cost_gap / alpha))",
  "hyperparams": {
    "paradigm_family": "ranking",
    "signal_family": "preference",
    "link_family": "sigmoid",
    "agg_family": "pairwise",
    "constraint_family": "cost_difference",
    "other_hparams": ""
  },
  "operators_used": ["logsigmoid"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    # Access log probabilities\n    log_prob_w = batch['log_prob_w']\n    log_prob_l = batch['log_prob_l']\n    # Access cost gap signal\n    cost_gap = batch['cost_gap']\n    # Optional: get alpha from extra or default to 1.0\n    alpha = float(extra.get('alpha', 1.0))\n    # Compute scaled difference\n    diff = ops.div(ops.mul(cost_gap, 1.0), alpha)\n    # Compute pairwise preference score\n    preference = ops.logsigmoid(ops.sub(log_prob_w, log_prob_l))\n    # Weight by the preference\n    weighted_pref = ops.mul(preference, batch['weight'])\n    # Return mean over batch as scalar loss\n    loss = ops.mean(weighted_pref)\n    return loss"
}

