{
  "name": "pairwise_cost_gap_preference_loss",
  "intuition": "Encourages preferred pairs by weighting the log probability difference with cost gap, promoting higher likelihood for better (lower cost) samples.",
  "pseudocode": "loss = weighted_mean( logsigmoid( (log_prob_w - log_prob_l) * cost_gap ), weight )",
  "hyperparams": {
    "paradigm_family": "preference",
    "signal_family": "cost_gap",
    "link_family": "logarithmic",
    "agg_family": "pairwise",
    "constraint_family": "pairwise"
  },
  "operators_used": ["logsigmoid", "sub", "mul", "sum", "div", "clamp"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    eps = 1e-8\n    log_prob_w = batch['log_prob_w']\n    log_prob_l = batch['log_prob_l']\n    weight = batch['weight']\n    zeros = log_prob_w.new_zeros(log_prob_w.shape)\n    cost_gap = batch.get('cost_gap', batch.get('cost_b', zeros) - batch.get('cost_a', zeros))\n    diff_log_prob = ops.sub(log_prob_w, log_prob_l)\n    cost_gap = ops.clamp(cost_gap, min=-1e4, max=1e4)\n    score = ops.mul(diff_log_prob, cost_gap)\n    loss_vals = ops.logsigmoid(score)\n    weighted_loss = ops.mul(loss_vals, weight)\n    norm = ops.clamp(ops.sum(weight), min=eps)\n    return ops.div(ops.sum(weighted_loss), norm)"
}

{
  "name": "preference_diff_pairwise_logsigmoid",
  "intuition": "This loss computes the pairwise difference in log probabilities between preferred and less preferred options, scaled and stabilized with clamps, encouraging the model to assign higher probability to preferred choices. Using logsigmoid emphasizes the margin between options; aggregation by sum strengthens the penalty for large preference violations, promoting a consistent ranking.",
  "pseudocode": "loss = sum(-logsigmoid(clamp(alpha * scale * (log_prob_w - log_prob_l), -20, 20)))",
  "hyperparams": {
    "paradigm_family": "pairwise_margin",
    "signal_family": "cost_gap",
    "link_family": "logsigmoid",
    "agg_family": "sum",
    "constraint_family": "clamp_stabilized",
    "other_hparams": "optional"
  },
  "operators_used": ["logsigmoid", "clamp", "sum"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "cost_a", "cost_b"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n    alpha = float(extra.get('alpha', extra.get('hyperparams', {}).get('alpha', 1.0)))\n    scale = float(extra.get('hyperparams', {}).get('scale', 1.9496803035382082))\n    cost_a = batch['cost_a']\n    cost_b = batch['cost_b']\n    gap = (cost_b - cost_a).detach()\n    x = alpha * scale * (lpw - lpl) - 0.1 * gap\n    x = ops.clamp(x, -20.0, 20.0)\n    loss = -ops.logsigmoid(x)\n    if weight is not None:\n        loss = loss * weight\n    return ops.sum(loss)"
}

